// src/routes/verify-email.jsx
import React, { useEffect, useState } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { CheckCircle, XCircle, Loader2 } from 'lucide-react';
import { Button } from '../components/ui/button';
import { Logo } from '../components/logo';

export default function VerifyEmail() {
  const navigate = useNavigate();
  const location = useLocation();
  const [status, setStatus] = useState('loading');
  const [message, setMessage] = useState('');

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const token = params.get('token');

    console.log('Verification token:', token);

    if (!token) {
      setStatus('error');
      setMessage('No verification token found.');
      return;
    }

    // Use the API URL from environment or fallback
    const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
    const verifyUrl = `${apiUrl}/auth/verify?token=${token}`;
    
    console.log('Calling verification URL:', verifyUrl);

    // Call backend verification endpoint with timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout

    fetch(verifyUrl, {
      method: 'GET',
      signal: controller.signal,
      headers: {
        'Accept': 'text/plain',
        'Content-Type': 'text/plain',
      },
    })
      .then(response => {
        clearTimeout(timeoutId);
        console.log('Response status:', response.status);
        console.log('Response headers:', response.headers);
        
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.text();
      })
      .then(data => {
        console.log('Response data:', data);
        if (data.includes('successfully') || data.includes('verified')) {
          setStatus('success');
          setMessage('Email verified successfully! You can now login.');
          setTimeout(() => navigate('/login'), 3000);
        } else {
          setStatus('error');
          setMessage(data || 'Verification failed. Please try again.');
        }
      })
      .catch(error => {
        clearTimeout(timeoutId);
        console.error('Verification error details:', error);
        
        if (error.name === 'AbortError') {
          setStatus('error');
          setMessage('Request timed out. Please check your internet connection.');
        } else if (error.message.includes('Failed to fetch')) {
          setStatus('error');
          setMessage('Cannot connect to the server. Please make sure the backend is running on port 8080.');
        } else {
          setStatus('error');
          setMessage(`Verification failed: ${error.message}. Please try again.`);
        }
      });
  }, [location, navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center p-6 bg-gradient-to-br from-background via-background/95 to-emerald/5">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="w-full max-w-md"
      >
        <div className="text-center mb-8">
          <Logo className="justify-center" />
          <h1 className="text-2xl font-semibold text-gradient mt-4">Email Verification</h1>
        </div>

        <div className="glass rounded-2xl p-8 text-center">
          {status === 'loading' && (
            <>
              <Loader2 className="h-16 w-16 text-emerald animate-spin mx-auto mb-4" />
              <h2 className="text-xl font-semibold mb-2">Verifying Your Email...</h2>
              <p className="text-muted-foreground">Please wait while we verify your email address.</p>
              <p className="text-xs text-muted-foreground mt-2">If this takes too long, check your internet connection.</p>
            </>
          )}

          {status === 'success' && (
            <>
              <CheckCircle className="h-16 w-16 text-emerald mx-auto mb-4" />
              <h2 className="text-xl font-semibold text-emerald mb-2">✅ Email Verified!</h2>
              <p className="text-muted-foreground mb-4">{message}</p>
              <p className="text-sm text-muted-foreground">Redirecting to login...</p>
            </>
          )}

          {status === 'error' && (
            <>
              <XCircle className="h-16 w-16 text-destructive mx-auto mb-4" />
              <h2 className="text-xl font-semibold text-destructive mb-2">❌ Verification Failed</h2>
              <p className="text-muted-foreground mb-6">{message}</p>
              <div className="space-y-3">
                <Link to="/login">
                  <Button className="w-full rounded-lg bg-emerald text-primary-foreground shadow-glow hover:bg-emerald/90">
                    Go to Login
                  </Button>
                </Link>
                <div className="flex gap-2">
                  <button 
                    onClick={() => window.location.reload()} 
                    className="flex-1 rounded-lg border border-emerald/30 text-emerald hover:bg-emerald/10 py-2 px-4 text-sm transition-colors"
                  >
                    Try Again
                  </button>
                  <button 
                    onClick={() => {
                      // Manual verification with token
                      const token = new URLSearchParams(location.search).get('token');
                      navigator.clipboard.writeText(`curl -X GET "http://localhost:8080/api/auth/verify?token=${token}"`);
                      alert('Copy this command to test in terminal:\n\ncurl -X GET "http://localhost:8080/api/auth/verify?token=' + token + '"');
                    }} 
                    className="flex-1 rounded-lg border border-border hover:bg-foreground/[0.03] py-2 px-4 text-sm transition-colors text-muted-foreground"
                  >
                    Copy Test Command
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      </motion.div>
    </div>
  );
}
